export const ICONS = { ELEMENT, REACTION, ACHIEVEMENT, BIOME, THEME, SYSTEM };

// key -> 外层 <svg> 属性。className 交给调用方决定尺寸。
function wrap(inner, cls, extra) {
  return `<svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg"` +
    ` fill="none"${cls ? ` class="${cls}"` : ''}${extra || ''}>${inner}</svg>`;
}

/** 元素栏 / 调色板用 */
export function elementIcon(key, cls) { return wrap(ELEMENT[key], cls); }
/** 发现图鉴用 */
export function reactionIcon(key, cls) { return wrap(REACTION[key], cls); }
/** 成就用；locked=true 时返回锁形（无对应图标的条目也走这里） */
export function achievementIcon(key, cls) {
  return ACHIEVEMENT[key]
    ? wrap(ACHIEVEMENT[key], cls)
    : LOCK_SVG(cls);
}
/** 地图场景用 */
export function biomeIcon(key, cls) { return wrap(BIOME[key], cls); }
/** 背景主题用 */
export function themeIcon(key, cls) { return wrap(THEME[key], cls); }
/** 系统按键 / UI 按钮用（线稿，跟随 currentColor） */
export function systemIcon(key, cls) { return wrap(SYSTEM[key], cls); }

/** 未解锁占位：线稿挂锁，跟随 currentColor */
export const LOCK_SVG = (cls) => wrap(
  '<g stroke="currentColor" fill="none" stroke-width="2" ' +
  'stroke-linecap="round" stroke-linejoin="round">' +
  '<rect x="9" y="14.5" width="14" height="10" rx="2"/>' +
  '<path d="M12 14.5 V11 a4 4 0 0 1 8 0 v3.5"/>' +
  '<circle cx="16" cy="19.4" r="1.4" fill="currentColor" stroke="none"/>' +
  '</g>', cls);

export default ICONS;
